/bin/bash -lc "node --input-type=module <<'EOF'
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { once } from 'node:events';
import { resolve } from 'node:path';
const directory = await mkdtemp(resolve('.workboard-launch-'));
const child = spawn('npm', ['start'], { detached: true, env: { ...process.env, PORT: '0', DB_PATH: resolve(directory, 'launch.sqlite') }, stdio: ['ignore', 'pipe', 'pipe'] });
try {
  const port = await new Promise((resolvePort, reject) => {
    let output = '';
    const timer = setTimeout(() => reject(new Error('Launch timed out')), 5000);
    child.once('error', reject);
    child.stdout.on('data', chunk => {
      output += chunk;
      const match = /listening on port (\\d+)/.exec(output);
      if (match) { clearTimeout(timer); resolvePort(match[1]); }
    });
  });
  const response = await fetch("'`http://127.0.0.1:${port}/health`);
  if (response.status !== 200 || JSON.stringify(await response.json()) !== '"'{\"status\":\"ok\"}') throw new Error('Health failed');
  console.log('npm start and GET /health passed');
} finally {
  const exited = once(child, 'exit');
  process.kill(-child.pid, 'SIGTERM');
  await exited;
  await rm(directory, { recursive: true, force: true });
}
EOF
"

